const visualSchema = {type:'object',additionalProperties:false,required:['type','title','description','sourceName','labels','values'],properties:{type:{type:'string',enum:['none','chart','process','comparison','timeline','matrix','cycle','architecture','risk-map','source-image']},title:{type:'string'},description:{type:'string'},sourceName:{type:'string'},labels:{type:'array',items:{type:'string'}},values:{type:'array',items:{type:'number'}}}} as const;
